CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY role_read_self ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.support_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(length(phone) BETWEEN 8 AND 30), email text NOT NULL CHECK(length(email) <= 255), question text NOT NULL CHECK(length(question) BETWEEN 1 AND 2000), household_size integer NOT NULL CHECK(household_size BETWEEN 1 AND 100), monthly_spend numeric NOT NULL CHECK(monthly_spend >= 0), spending_topic text NOT NULL CHECK(length(spending_topic) BETWEEN 1 AND 100), consent boolean NOT NULL CHECK(consent), status text NOT NULL DEFAULT 'aberto' CHECK(status IN ('aberto','respondido','concluido')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.support_requests TO authenticated;
GRANT ALL ON public.support_requests TO service_role;
ALTER TABLE public.support_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_read ON public.support_requests FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY support_create ON public.support_requests FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid() AND status = 'aberto');
CREATE POLICY support_manage ON public.support_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY support_delete ON public.support_requests FOR DELETE TO authenticated USING(user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.support_requests(id) ON DELETE CASCADE, sender_id uuid NOT NULL, body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.support_messages TO authenticated;
GRANT ALL ON public.support_messages TO service_role;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON public.support_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_requests r WHERE r.id=request_id AND (r.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY message_insert ON public.support_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.support_requests r WHERE r.id=request_id AND r.status <> 'concluido' AND (r.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.newsletter_subscribers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(length(email) BETWEEN 5 AND 255), consent boolean NOT NULL CHECK(consent), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.newsletter_subscribers TO anon, authenticated;
GRANT SELECT, DELETE ON public.newsletter_subscribers TO authenticated;
GRANT ALL ON public.newsletter_subscribers TO service_role;
ALTER TABLE public.newsletter_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY newsletter_subscribe ON public.newsletter_subscribers FOR INSERT TO anon, authenticated WITH CHECK(consent=true);
CREATE POLICY newsletter_admin ON public.newsletter_subscribers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY newsletter_remove ON public.newsletter_subscribers FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin') OR email = (auth.jwt()->>'email'));
CREATE TABLE public.community_notices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 100), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.community_notices TO authenticated;
GRANT ALL ON public.community_notices TO service_role;
ALTER TABLE public.community_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY notice_read ON public.community_notices FOR SELECT TO authenticated USING(recipient_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY notice_send ON public.community_notices FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY notice_mark_read ON public.community_notices FOR UPDATE TO authenticated USING(recipient_id=auth.uid()) WITH CHECK(recipient_id=auth.uid());
REVOKE UPDATE ON public.community_notices FROM authenticated;
GRANT UPDATE(read_at) ON public.community_notices TO authenticated;